"use strict";(globalThis.webpackChunkmy_website||=[]).push([[6935],{86244(e){e.exports=JSON.parse('{"slug":"did","title":"DID","short":"An identifier you create and control yourself, with no central registrar; the record that resolves it lives on a blockchain or other decentralized system rather than in a single company\'s database.","category":"general","aliases":["Decentralized Identifier"],"mentalModel":"Like a username that no platform can revoke. The identifier is yours, the proofs that back it are yours, and the network only acts as a public ledger of who is allowed to update them.","related":[],"sources":[],"link":null,"level":"intermediate","body":"DIDs are designed to let individuals carry their identity between services without depending on a specific provider to vouch for them."}')}}]);